  const [activeDomain, setActiveDomain] = useState<AdvancedSlaDomain>(ADVANCED_SLA_DOMAINS[0]); const [activeTab, setActiveTab] = useState<WorkbenchTab>("rules"); const [search, setSearch] = useState(""); const [statusFilter, setStatusFilter] = useState<RuleStatusFilter>("all");
  const [csv, setCsv] = useState(""); const [csvSourceName, setCsvSourceName] = useState(""); const [newProfileName, setNewProfileName] = useState(""); const [newProfileDescription, setNewProfileDescription] = useState(""); const [conflict, setConflict] = useState(false);
  const [governanceMode] = useState(() => typeof window !== "undefined" && new URLSearchParams(window.location.search).get("advancedSlaGovernance") === "1");
  const [ruleDialog, setRuleDialog] = useState<RuleDialogState | null>(null); const [moreRuleId, setMoreRuleId] = useState<string | null>(null); const [detailSelection, setDetailSelection] = useState<RuleSelection | null>(null); const [deleteSelection, setDeleteSelection] = useState<RuleSelection | null>(null); const [csvDialogOpen, setCsvDialogOpen] = useState(false); const [policyDialogOpen, setPolicyDialogOpen] = useState(false); const fileRef = useRef<HTMLInputElement>(null);
  const moreTriggerRef = useRef<HTMLButtonElement | null>(null);
  const moreMenuRef = useRef<HTMLDivElement | null>(null);
