    items()[0]?.focus();
    const keydown = (event: KeyboardEvent) => {
      if (event.key === "Escape" || event.key === "Tab") { if (event.key === "Escape") event.preventDefault(); moreTriggerRef.current?.focus(); setMoreRuleId(null); return; }
      if (!menu?.contains(document.activeElement)) return;
      const enabled = items(); if (!enabled.length) return;
      const current = enabled.indexOf(document.activeElement as HTMLButtonElement);
      const next = event.key === "ArrowDown" ? (current + 1) % enabled.length : event.key === "ArrowUp" ? (current - 1 + enabled.length) % enabled.length : event.key === "Home" ? 0 : event.key === "End" ? enabled.length - 1 : null;
      if (next !== null) { event.preventDefault(); enabled[next]?.focus(); }
    };
    const outside = (event: PointerEvent) => { if (event.target instanceof Node && !menu?.contains(event.target) && !moreTriggerRef.current?.contains(event.target)) setMoreRuleId(null); };
    document.addEventListener("keydown", keydown); document.addEventListener("pointerdown", outside);
