  const togglePause = () => { const runtime = view.runtimeControl; if (!runtime) return; void runMutation(runtime.paused ? "恢复运行" : "暂停运行", "/api/procurement/advanced-sla/runtime-control", { method: "PUT", body: { profileId: runtime.profileId, profileVersion: runtime.profileVersion, expectedVersion: runtime.version, paused: !runtime.paused, reason: runtime.paused ? "人工恢复 Advanced SLA" : "人工触发 kill switch" } }, "pause", { action: "runtime", targetId: runtime.profileId, profileVersion: runtime.profileVersion, expectedVersion: runtime.version, paused: !runtime.paused }); };
