    try { const response = await apiRequest<unknown>("/api/procurement/advanced-sla/imports/preview", { method: "POST", body: { domain: activeDomain, sourceName: sourceNameInput.trim(), profileId: view.draft.id, expectedVersion: view.draft.version, csv: csvInput } }); const preview = isRecord(response) ? parseAdvancedSlaImportPreview(response.item) : null; if (!preview) throw new Error("CSV 预览返回无效"); const refreshed = await fetchDashboard(); const normalized = normalizeAdvancedSlaDashboard(refreshed); if (normalized.state === "error" || !isRecord(refreshed)) throw new Error("CSV 预览后无法重载持久化数据"); const retained = reconcileAdvancedSlaImportPreview(preview, normalized.draft); setPayload(refreshed); if (!retained) { setEditor(isAdvancedSlaProfileV2(normalized.draft) ? createEditorState(normalized.draft) : null); throw new Error("草稿版本已变化，待定预览已丢弃"); } setImportPreview(retained); setNotice("CSV 已持久化验证；尚未应用"); }
