  const confirmDeleteRule = () => { if (!editor || readOnly || busy || !deleteSelection) return; const nextEditor = removeEditorRule(editor, deleteSelection.domain, deleteSelection.ruleId); setDeleteSelection(null); setDetailSelection(null); setMoreRuleId(null); void persistEditor(nextEditor, "规则删除"); };

