    <header className={cn("flex items-start justify-between gap-6", READYWORK_INTEGRATED_HEADER_ACTION_GUTTER_CLASS)}><div><div className="mb-3 flex items-center gap-2 text-xs text-slate-400"><span>设置</span><ChevronRight className="size-3" /><span className="text-slate-600">高级服务等级设置</span></div><h1 className={READYWORK_PAGE_TITLE_CLASS}>高级服务等级设置</h1><p className="mt-1 text-[13.5px] text-slate-500">按规则域手动配置或通过 CSV 导入 Readywork 监控采购订单所用的业务规则。</p></div>{governanceMode && <div className="flex shrink-0 items-center gap-2"><button type="button" onClick={refreshManually} className="flex h-10 items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 text-xs font-medium text-slate-700"><RefreshCw className="size-4" />刷新</button>{editor && <button type="button" onClick={() => setPolicyDialogOpen(true)} className="flex h-10 items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 text-xs font-medium text-slate-700"><Settings2 className="size-4" />策略设置</button>}<button type="button" disabled={readOnly || !editor?.dirty || Boolean(busy)} onClick={saveEditor} className="flex h-10 items-center gap-2 rounded-xl border border-blue-200 bg-white px-4 text-xs font-semibold text-blue-700 disabled:opacity-50"><Save className="size-4" />保存草稿</button><button type="button" disabled={!view.draft || !isAdvancedSlaProfileV2(view.draft) || approveDisabled || Boolean(editor?.dirty) || Boolean(busy)} onClick={publish} className="flex h-10 items-center gap-2 rounded-xl bg-blue-600 px-4 text-xs font-semibold text-white disabled:opacity-50"><Upload className="size-4" />发布</button></div>}</header>
